/* ============ Storage ============ */
function normalize(s) {
  const arr = (x, d) => (Array.isArray(x) ? x : d);
  const out = {
    _v: SEED_V,
    users: arr(s.users, seed().users),
    units: arr(s.units, []),
    expenses: arr(s.expenses, []),
    attendance: arr(s.attendance, []),
    lives: arr(s.lives, []),
    extras: arr(s.extras, []),
    media: arr(s.media, []),
    tasks: arr(s.tasks, []),
    chat: arr(s.chat, []),
  };
  out.users = out.users.map((u) => ({ avatar: "", saleBonus: false, ...(u.role === "owner" ? {} : { password: "" }), ...u, ...(u.id === "u_omen" || u.id === "u_beceng" ? { saleBonus: true } : {}) }));
  out.units = out.units.map((u) => ({ investorCode: "", soldAt: null, inDate: "", odometer: 0, sellPrice: 0, buyPrice: 0, status: "proses", ...u }));
  out.media = out.media.map((m) => ({ category: "ADS", verified: false, note: "", date: "", ...m }));
  out._sbFix = s._sbFix === true;
  return out;
}
async function loadState() {
  try {
    const r = await window.storage.get(STORE_KEY, true);
    if (r && r.value) { const p = JSON.parse(r.value); if (p && p._v === SEED_V) return normalize(p); }
  } catch (e) {}
  const s = seed(); try { await window.storage.set(STORE_KEY, JSON.stringify(s), true); } catch (e) {} return s;
}
async function saveState(s) { try { await window.storage.set(STORE_KEY, JSON.stringify(s), true); } catch (e) {} }

// Hapus foto absen & bukti live yang lebih tua dari PHOTO_TTL_DAYS hari (catatannya tetap disimpan).
const PHOTO_TTL_DAYS = 2;
function prunePhotos(state) {
  const d = new Date(); d.setDate(d.getDate() - PHOTO_TTL_DAYS);
  const cutoff = `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
  let changed = false;
  const strip = (arr) => (arr || []).map((r) => {
    if (r && r.photo && r.date && r.date < cutoff) { changed = true; return { ...r, photo: "" }; }
    return r;
  });
  const next = { ...state, attendance: strip(state.attendance), lives: strip(state.lives) };
  return { next, changed };
}

// Bonus penjualan sekarang dihitung dinamis, jadi bonus auto yang lama dibersihkan agar tidak dobel.
function stripAutoExtras(s) {
  const before = (s.extras || []).length;
  s.extras = (s.extras || []).filter((e) => !e.auto);
  return s.extras.length !== before;
}
// Perbaikan sekali-jalan: pastikan Omen & Beceng aktif bonus penjualannya (toggle sempat OFF).
function fixSaleBonus(s) {
  if (s._sbFix) return false;
  (s.users || []).forEach((u) => { if (u.id === "u_omen" || u.id === "u_beceng") u.saleBonus = true; });
  s._sbFix = true;
  return true;
}

