            {(u.saleBonus || total !== 0) && <p className={`text-[11px] font-semibold mb-1.5 flex items-center gap-1 ${total < 0 ? "text-rose-500" : "text-orange-500"}`}><Gift size={12} />Extra cash bulan ini: {rp(total)}</p>}
